import React from "react";

function MsgHistory({obj}) {
  const headers = ["Date", "Message"];
  return (
    <div className="w-full h-screen relative  sm:top-10  flex justify-center items-center text-c">

    <table className=" border-solid border-2    w-full h-screen ">
      <thead>
        <tr>
          {headers.map((h) => {
            return <td>{h}</td>;
          })}
        </tr>
      </thead>
      <tbody>
        {
          obj.map((o)=>{
            return(
              <tr>
                <td>{o.date}</td>
                <td>{o.msg}</td>
              </tr>
            )
          })
        }
      </tbody>
    </table>
    </div>
  );
}

export default MsgHistory;
